"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


def reject_constant(value):
    raise ValueError("invalid JSON constant: " + value)


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or any(not isinstance(column, str) for column in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    result = datetime.fromisoformat(value)
    return result.replace(tzinfo=now.tzinfo) if result.tzinfo is None else result


def routine(row, now):
    every = row["every"]
    if not re.fullmatch(r"[1-9][0-9]*[rsmhd]", every):
        return None
    last_time = row["last_time"]
    try:
        last = timestamp(last_time, now) if last_time else None
    except ValueError:
        return None
    code = row["last_code"]
    if code == "":
        code = None
    elif code != "running":
        if not re.fullmatch(r"[+-]?[0-9]+", code):
            return None
        code = int(code)
    next_time = None
    if last is not None and every.endswith(("s", "m", "h", "d")):
        seconds = {"s": 1, "m": 60, "h": 3600, "d": 86400}[every[-1]]
        next_time = last + timedelta(seconds=int(every[:-1]) * seconds)
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_time is not None and now >= next_time:
        state = "overdue"
    else:
        state = "ok"
    rendered = (next_time.astimezone(timezone.utc).isoformat(timespec="seconds")
                .replace("+00:00", "Z") if next_time is not None else None)
    return {"name": row["name"], "every": every, "last_time": last_time or None,
            "last_code": code, "state": state, "next": rendered}


def schedule(row, now):
    try:
        at = timestamp(row["at"], now)
    except ValueError:
        return None
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    counts = {"routines": dict.fromkeys(("running", "never", "failed", "overdue", "ok"), 0),
              "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)}
    result = {"v": 1, "routines": [], "schedule": [], "counts": counts, "bad": []}
    required = {"routines": ("name", "every", "last_time", "last_code"),
                "schedule": ("name", "at", "claimed")}
    for table, convert in (("routines", routine), ("schedule", schedule)):
        rows, problems = read_table(node, table)
        result["bad"].extend(problems)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    result["bad"].append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            if (not isinstance(row, dict) or not isinstance(name, str) or not name
                    or any(key not in row for key in required[table])
                    or any(not isinstance(value, str) for value in row.values())):
                item = None
            else:
                item = convert(row, now)
            if item is None:
                result["bad"].append({"table": table, "row": index, "why": "bad_row"})
            else:
                result[table].append(item)
                counts[table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    result["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables read-only")
    parser.add_argument("node", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.node.is_dir():
        parser.error("node is not a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    print(json.dumps(summarize(args.node, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
